First, we shall sketch! [asy]
pair A, B, C, D;
A = (0,90);
B = (0,0);
C = (56,0);
D = (56*90/(90+106),0);
draw(A--B--C--cycle);
draw(A--D);
label("$A$", A, NW);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, NE);
